import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const root = path.resolve(__dirname, "..");

const entryFiles = [
  "packages/@fmg/legacy-ui/src/components/fill-box.ts",
  "packages/@fmg/legacy-ui/src/components/slider-input.ts",
  "packages/@fmg/legacy-ui/src/config/heightmap-templates.ts",
  "packages/@fmg/legacy-ui/src/config/precreated-heightmaps.ts"
];

const outFile = "public/generated/public-bundle.js";

const transpileOptions = {
  compilerOptions: {
    target: ts.ScriptTarget.ES2020,
    module: ts.ModuleKind.None,
    removeComments: false,
    sourceMap: false
  }
};

const sections = [
  "/* Auto-generated by scripts/build-public-bundle.mjs. Do not edit directly. */"
];

for (const relativeFile of entryFiles) {
  const absoluteFile = path.join(root, relativeFile);
  const sourceText = await readFile(absoluteFile, "utf8");
  const result = ts.transpileModule(sourceText, {
    ...transpileOptions,
    fileName: relativeFile
  });

  sections.push(`// ----- ${relativeFile}`);
  sections.push(result.outputText.trim());
}

const absoluteOutFile = path.join(root, outFile);
await mkdir(path.dirname(absoluteOutFile), { recursive: true });
await writeFile(absoluteOutFile, `${sections.join("\n\n")}\n`, "utf8");

console.log(`Built ${outFile} from ${entryFiles.length} TypeScript sources`);
